import 'package:fixed/fixed.dart';

void main() {
  final t1 = Fixed.fromNum(1, decimalDigits: 2); // 1.00
  final t2 = Fixed.fromNum(1, decimalDigits: 3); // 1.000
  final add = t1 + Fixed.ten;
  final multiply = t1 * t2;
  print(add); // 11.00
  print(multiply); // 1.00000
}
